"""The evaluation grid. Everything the README quotes is regenerated by this file.

    python -m src.eval.run_eval                       # full grid + ablations + stats
    python -m src.eval.run_eval --scenario night_do_crash
    python -m src.eval.run_eval --seeds 12
    python -m src.eval.run_eval --no-ablations

Outputs (all CSV, all under outputs/):
    agent_runs.csv          one row per (scenario, controller, seed)
    agent_summary.csv       median + IQR per scenario x controller
    agent_stats.csv         paired Wilcoxon, agent vs each baseline, with p and n
    safety.csv              unsafe-applied per controller across the whole grid
    ablations.csv           forecast on/off, guardrails on/off, weight source
    anomaly_detection.csv   recall on the injected sensor-fault events
    forecast_horizon.csv    per-channel, per-horizon RMSE on held-out real sites

Nothing here touches the network, and every number is written to a file rather than printed
into a document by hand.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

from src.agent.loop import AgentRun, Perception  # noqa: E402
from src.common.runtime import MODELS_DIR, OUTPUTS_DIR, load_config, set_seed  # noqa: E402
from src.eval import baselines as B  # noqa: E402
from src.eval import metrics as M  # noqa: E402
from src.twin.scenarios import load_scenarios  # noqa: E402


# ======================================================================================
# Perception loading
# ======================================================================================
def load_perception(source: str = "federated", with_forecast: bool = True) -> Perception:
    """Load a pretrained stack. Missing pieces are simply absent - the loop degrades."""
    from src.perception.explain import RiskExplainer
    from src.perception.forecaster import LSTMForecaster
    from src.perception.regimes import RegimeModel
    from src.perception.risk import RiskModel

    forecaster = None
    if with_forecast:
        path = {
            "federated": MODELS_DIR / "forecaster_federated.pt",
            "central": MODELS_DIR / "forecaster_central.pt",
        }.get(source)
        if path is None:
            locals_ = sorted(MODELS_DIR.glob("forecaster_local_*.pt"))
            path = locals_[0] if locals_ else None
        if path is not None and Path(path).exists():
            forecaster = LSTMForecaster.load(path)

    regimes = RegimeModel.load(MODELS_DIR / "regimes.pkl") if (MODELS_DIR / "regimes.pkl").exists() else None
    risk = RiskModel.load(MODELS_DIR / "risk_model.pkl") if (MODELS_DIR / "risk_model.pkl").exists() else None
    explainer = RiskExplainer(risk) if risk is not None else None
    return Perception(forecaster=forecaster, regimes=regimes, risk=risk, explainer=explainer)


# ======================================================================================
# The grid
# ======================================================================================
def run_grid(
    scenarios: List[str],
    controllers: List[str],
    seeds: List[int],
    perception: Perception,
    verbose: bool = True,
) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    total = len(scenarios) * len(controllers) * len(seeds)
    i = 0
    for sid in scenarios:
        for ctrl in controllers:
            for seed in seeds:
                i += 1
                set_seed(seed)
                run = AgentRun(sid, controller=ctrl, seed=seed, perception=perception).run()
                m = run.metrics()
                m["source"] = "federated"
                rows.append(m)
                if verbose:
                    print(f"  [{i:4d}/{total}] {sid:22s} {ctrl:18s} seed={seed:<6d} "
                          f"crit={m['time_critical_h']:5.2f}h  DO-risk={m.get('risk_h_do', 0):5.2f}h  "
                          f"unsafe={m['unsafe_applied']}")
    return pd.DataFrame(rows)


# ======================================================================================
# Ablations
# ======================================================================================
def run_ablations(scenarios: List[str], seeds: List[int], verbose: bool = True) -> pd.DataFrame:
    """The three questions a reader will ask: does the forecast help, do the guardrails cost
    anything, and does it matter which federated regime produced the weights?"""
    rows: List[Dict[str, Any]] = []
    agent_cfg = load_config("agent")

    variants: List[Dict[str, Any]] = [
        # `full` is the SHIPPED configuration, correction included. `no_lstm_correction` is
        # the variant that scores better, kept in the grid so the cost of shipping the learned
        # forecaster on the actuator path stays measured rather than asserted.
        {"name": "full", "source": "federated", "forecast": True, "guardrails": True, "use_forecaster": True},
        {"name": "no_lstm_correction", "source": "federated", "forecast": True, "guardrails": True, "use_forecaster": False},
        {"name": "no_forecast_at_all", "source": "federated", "forecast": False, "guardrails": True, "use_forecaster": False},
        {"name": "no_guardrails", "source": "federated", "forecast": True, "guardrails": False, "use_forecaster": True},
        # Weight source, at the shipped setting - the correction is what carries it through.
        {"name": "weights_independent_local", "source": "independent-local", "forecast": True, "guardrails": True, "use_forecaster": True},
        {"name": "weights_central", "source": "central", "forecast": True, "guardrails": True, "use_forecaster": True},
        # The learned dynamics model vs the hand-written one. `full` uses whatever
        # `predictive.world_model` ships as, so this row is what isolates it.
        {"name": "no_world_model", "source": "federated", "forecast": True, "guardrails": True, "use_forecaster": True, "world_model": False},
    ]

    for v in variants:
        perception = load_perception(v["source"], with_forecast=v["forecast"])
        if v["forecast"] and perception.forecaster is None:
            if verbose:
                print(f"  skip ablation '{v['name']}': no weights for source '{v['source']}'")
            continue
        pred = {**agent_cfg["predictive"], "use_forecaster": v["use_forecaster"]}
        if "world_model" in v:
            pred["world_model"] = v["world_model"]
        cfg = {**agent_cfg, "predictive": pred}
        for sid in scenarios:
            for seed in seeds:
                set_seed(seed)
                run = AgentRun(
                    sid, controller="predictive", seed=seed, perception=perception,
                    agent_cfg=cfg, guardrails_enabled=v["guardrails"],
                ).run()
                m = run.metrics()
                m.update({"ablation": v["name"], "source": v["source"],
                          "forecast": v["forecast"], "guardrails": v["guardrails"],
                          "lstm_correction": v["use_forecaster"],
                          "world_model": v.get("world_model", agent_cfg["predictive"].get("world_model", False))})
                rows.append(m)
        if verbose:
            sub = [r for r in rows if r["ablation"] == v["name"]]
            print(f"  {v['name']:26s} median DO-risk "
                  f"{np.median([r.get('risk_h_do', np.nan) for r in sub]):6.2f} h   "
                  f"unsafe total {sum(r['unsafe_applied'] for r in sub)}")
    return pd.DataFrame(rows)


# ======================================================================================
# Anomaly detection on the injected sensor faults
# ======================================================================================
def run_anomaly_eval(seeds: List[int], perception: Perception, verbose: bool = True) -> pd.DataFrame:
    """Recall on the `sensor_fault` scenario's injected events, plus the false-positive rate.

    The honest framing: HDBSCAN's noise label detects "unlike anything in training". It is not
    a fault classifier, and the false-positive rate here is the price of that generality.
    """
    from src.twin.scenarios import get_scenario

    rows: List[Dict[str, Any]] = []
    if perception.regimes is None:
        return pd.DataFrame(rows)

    for seed in seeds:
        scenario = get_scenario("sensor_fault").reset()
        windows = [(p.start_h, p.end_h) for p in scenario.perturbations if p.kind == "sensor_fault"]
        set_seed(seed)
        # AgentRun.run() returns the RunResult, not the AgentRun.
        result = AgentRun("sensor_fault", controller="predictive", seed=seed,
                          perception=perception, with_shadow=False).run()
        flags = [d.anomaly for d in result.decisions]
        times = [d.t_hours for d in result.decisions]
        res = M.anomaly_recall(flags, windows, times)
        res.update({"seed": seed, "scenario": "sensor_fault"})
        rows.append(res)
        if verbose:
            print(f"  seed {seed}: {res['detected']}/{res['events']} fault events flagged, "
                  f"FPR {res['false_positive_rate']:.3f}")
    return pd.DataFrame(rows)


# ======================================================================================
# Forecast quality on held-out real sites
# ======================================================================================
def run_forecast_eval(verbose: bool = True) -> pd.DataFrame:
    """Per-channel, per-horizon RMSE on real sites, for each available weight source."""
    from src.data import registry as R
    from src.perception.forecaster import LSTMForecaster

    rows: List[Dict[str, Any]] = []
    sources = {
        "federated": MODELS_DIR / "forecaster_federated.pt",
        "central": MODELS_DIR / "forecaster_central.pt",
    }
    locals_ = sorted(MODELS_DIR.glob("forecaster_local_*.pt"))
    if locals_:
        sources["independent_local"] = locals_[0]

    import json

    manifest_path = MODELS_DIR / "manifest.json"
    holdout_ids = []
    if manifest_path.exists():
        holdout_ids = json.loads(manifest_path.read_text(encoding="utf-8")).get("holdout_sites", [])

    sites = [s for s in R.load_all(min_channels=3) if not holdout_ids or s.client_id in holdout_ids]
    if not sites:
        return pd.DataFrame(rows)

    for name, path in sources.items():
        if not Path(path).exists():
            continue
        model = LSTMForecaster.load(path)
        for site in sites:
            X, Y, Mk = model.make_windows(site.matrix(model.channels), site.mask_matrix(model.channels), stride=12)
            if len(X) == 0:
                continue
            import torch

            with torch.no_grad():
                model.net.eval()
                pred = model.net(torch.from_numpy(X)).numpy()
            for j, ch in enumerate(model.channels):
                per_h = M.per_horizon_rmse(
                    pred[:, :, [j]] * model.scales[j], Y[:, :, [j]] * model.scales[j], Mk[:, :, [j]]
                )
                for h, rmse in enumerate(per_h):
                    if np.isfinite(rmse):
                        rows.append({"source": name, "site": site.client_id, "channel": ch,
                                     "horizon_step": h + 1,
                                     # One step is one sample of THIS site's series (15 min on
                                     # the pond data), not the twin's 5-minute step.
                                     "horizon_minutes": (h + 1) * site.cadence_minutes,
                                     "rmse": float(rmse), "n_windows": int(len(X))})
        if verbose:
            sub = [r for r in rows if r["source"] == name and r["channel"] == "do"]
            if sub:
                print(f"  {name:20s} held-out DO RMSE (all horizons) "
                      f"{np.mean([r['rmse'] for r in sub]):.3f} mg/L over {len(sites)} sites")
    return pd.DataFrame(rows)


# ======================================================================================
def main() -> int:
    ap = argparse.ArgumentParser(description="Regenerate every evaluation table.")
    ap.add_argument("--scenario", action="append", default=None, help="restrict to scenario(s)")
    ap.add_argument("--seeds", type=int, default=10, help="number of seeds per cell")
    ap.add_argument("--controllers", nargs="*", default=None)
    ap.add_argument("--no-ablations", action="store_true")
    ap.add_argument("--no-forecast-eval", action="store_true")
    ap.add_argument("--quiet", action="store_true")
    args = ap.parse_args()

    verbose = not args.quiet
    scenarios = args.scenario or list(load_scenarios())
    controllers = args.controllers or B.DEFAULT_GRID
    seeds = [1000 + 7 * i for i in range(args.seeds)]
    OUTPUTS_DIR.mkdir(parents=True, exist_ok=True)

    print("=" * 78)
    print("AquaSentinel - evaluation grid")
    print("=" * 78)
    print(f"  scenarios   : {len(scenarios)}  {scenarios}")
    print(f"  controllers : {controllers}")
    print(f"  seeds       : {len(seeds)}")
    for c in controllers:
        print(f"    - {B.describe(c)}")
    print()

    perception = load_perception("federated")
    if perception.forecaster is None:
        print("  ! no pretrained forecaster found - running with the rule-based risk fallback.")
        print("    Run scripts/pretrain_federated.py first for the full evaluation.\n")

    print("Running the controller grid ...")
    runs = run_grid(scenarios, controllers, seeds, perception, verbose)
    runs.to_csv(OUTPUTS_DIR / "agent_runs.csv", index=False)

    summary = M.summarize_runs(runs)
    summary.to_csv(OUTPUTS_DIR / "agent_summary.csv", index=False)

    stats_frames = [
        M.compare_controllers(runs, metric=m)
        for m in ("risk_h_do", "time_critical_h", "time_in_risk_h", "intervention_cost")
    ]
    stats = pd.concat([f for f in stats_frames if not f.empty], ignore_index=True)
    stats.to_csv(OUTPUTS_DIR / "agent_stats.csv", index=False)

    safety = M.safety_table(runs)
    safety.to_csv(OUTPUTS_DIR / "safety.csv", index=False)

    print("\nSafety across the whole grid (unsafe-applied must be 0 for every guardrailed controller):")
    print(safety.to_string(index=False))

    print("\nAgent vs baselines on DO time-out-of-band (negative median_diff = agent better):")
    key = stats[(stats["metric"] == "risk_h_do") & (stats["controller_a"] == "predictive")]
    cols = ["scenario", "controller_b", "median_a", "median_b", "median_diff", "p", "n", "note"]
    print(key[cols].to_string(index=False))

    if not args.no_ablations:
        print("\nAblations ...")
        ab = run_ablations(scenarios, seeds[: max(len(seeds) // 2, 3)], verbose)
        if not ab.empty:
            ab.to_csv(OUTPUTS_DIR / "ablations.csv", index=False)

    print("\nAnomaly detection on injected sensor faults ...")
    an = run_anomaly_eval(seeds, perception, verbose)
    if not an.empty:
        an.to_csv(OUTPUTS_DIR / "anomaly_detection.csv", index=False)
        print(f"  event recall {an['recall'].mean():.2f} over {len(an)} seeds, "
              f"mean FPR {an['false_positive_rate'].mean():.3f}")

    if not args.no_forecast_eval:
        print("\nForecast quality on held-out real sites ...")
        fe = run_forecast_eval(verbose)
        if not fe.empty:
            fe.to_csv(OUTPUTS_DIR / "forecast_horizon.csv", index=False)

    print(f"\nAll tables written to {OUTPUTS_DIR}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
